<span class="line"><span style="color:#24292E;">  </span><span style="color:#6F42C1;">&quot;data-root&quot;</span><span style="color:#005CC5;">:</span><span style="color:#24292E;"> </span><span style="color:#032F62;">&quot;/data/docker_home&quot;</span></span>
